package com.shahboun.aqim;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.*;

public class IslamicToolsActivity extends Activity{
 final int G=Color.rgb(15,76,58),GD=Color.rgb(205,168,92),I=Color.rgb(248,244,235),T=Color.rgb(35,48,43),M=Color.rgb(105,110,108);android.graphics.Typeface c;SharedPreferences p;LinearLayout root;
 @Override public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("aqim",MODE_PRIVATE);getWindow().setStatusBarColor(I);getWindow().setNavigationBarColor(I);if(Build.VERSION.SDK_INT>=23)getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);try{if(Build.VERSION.SDK_INT>=26)c=getResources().getFont(getResources().getIdentifier("cairo","font",getPackageName()));}catch(Exception ignored){}show();}
 void show(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(16),dp(16),dp(16),dp(30));root.setBackgroundColor(I);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.addView(tx("أدوات إسلامية",27,G,true));card(tx("التاريخ الهجري الحسابي\n"+hijri(),18,T,true));LinearLayout corr=new LinearLayout(this);corr.setGravity(Gravity.CENTER);Button minus=btn("- يوم"),zero=btn("بدون تصحيح"),plus=btn("+ يوم");minus.setOnClickListener(v->{p.edit().putInt("hijriCorrection",-1).apply();show();});zero.setOnClickListener(v->{p.edit().putInt("hijriCorrection",0).apply();show();});plus.setOnClickListener(v->{p.edit().putInt("hijriCorrection",1).apply();show();});corr.addView(minus,new LinearLayout.LayoutParams(0,dp(52),1));corr.addView(zero,new LinearLayout.LayoutParams(0,dp(52),1));corr.addView(plus,new LinearLayout.LayoutParams(0,dp(52),1));card(corr);card(tx("التاريخ الهجري حسابي مع تصحيح يدوي ± يوم. المناسبات التي تعتمد على رؤية الهلال يُرجع فيها للإعلان الشرعي المحلي.",12,M,false));Button mosque=btn("المساجد القريبة");mosque.setOnClickListener(v->openMosques());add(mosque);Button zakat=btn("حاسبة الزكاة");zakat.setOnClickListener(v->showZakat());add(zakat);Button standby=btn("وضع Standby");standby.setOnClickListener(v->startActivity(new Intent(this,StandbyActivity.class)));add(standby);ScrollView s=new ScrollView(this);s.setFillViewport(true);s.addView(root);if(Build.VERSION.SDK_INT>=21)s.setOnApplyWindowInsetsListener((v,i)->{int top,bottom;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets z=i.getInsets(WindowInsets.Type.systemBars());top=z.top;bottom=z.bottom;}else{top=i.getSystemWindowInsetTop();bottom=i.getSystemWindowInsetBottom();}v.setPadding(0,top,0,bottom);return i;});setContentView(s);}
 String hijri(){int corr=p.getInt("hijriCorrection",0);if(Build.VERSION.SDK_INT>=24){String tzId=p.getString("tzId",java.util.TimeZone.getDefault().getID());android.icu.util.TimeZone itz=android.icu.util.TimeZone.getTimeZone(tzId);android.icu.util.IslamicCalendar h=new android.icu.util.IslamicCalendar(itz,new Locale("ar"));h.setTimeInMillis(System.currentTimeMillis()+corr*86400000L);String[] m={"محرم","صفر","ربيع الأول","ربيع الآخر","جمادى الأولى","جمادى الآخرة","رجب","شعبان","رمضان","شوال","ذو القعدة","ذو الحجة"};int mo=h.get(android.icu.util.Calendar.MONTH);return h.get(android.icu.util.Calendar.DAY_OF_MONTH)+" "+m[Math.max(0,Math.min(11,mo))]+" "+h.get(android.icu.util.Calendar.YEAR)+" هـ"+(corr==0?"":" • تصحيح "+(corr>0?"+1":"-1"));}return "يتطلب Android 7 أو أحدث";}
 void openMosques(){double[] ll=MainActivity.currentLatLon(this);Uri u=Uri.parse("geo:"+ll[0]+","+ll[1]+"?q="+Uri.encode("مسجد"));Intent i=new Intent(Intent.ACTION_VIEW,u);try{startActivity(i);}catch(Exception e){Intent web=new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.google.com/maps/search/?api=1&query="+Uri.encode("mosque")));try{startActivity(web);}catch(Exception ignored){Toast.makeText(this,"لا يوجد تطبيق خرائط متاح",Toast.LENGTH_LONG).show();}}}
 void showZakat(){final Dialog d=new Dialog(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(18),dp(18),dp(18),dp(18));box.setBackground(bg(I));box.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);box.addView(tx("حاسبة زكاة إرشادية",23,G,true));box.addView(tx("تحسب 2.5% من الصافي إذا بلغ النصاب المدخل. المسائل التفصيلية قد تحتاج سؤال أهل العلم.",12,M,false));EditText assets=num("إجمالي المال/عروض التجارة"),debts=num("الديون المستحقة القابلة للخصم"),nisab=num("قيمة النصاب المعتمد");box.addView(assets,new LinearLayout.LayoutParams(-1,dp(56)));box.addView(debts,new LinearLayout.LayoutParams(-1,dp(56)));box.addView(nisab,new LinearLayout.LayoutParams(-1,dp(56)));TextView result=tx("",17,T,true);box.addView(result);Button calc=btn("احسب");calc.setTextColor(Color.WHITE);calc.setBackground(bg(G));calc.setOnClickListener(v->{double a=val(assets),de=val(debts),n=val(nisab),net=Math.max(0,a-de),z=(n>0&&net>=n)?net*.025:0;result.setText("الصافي: "+money(net)+"\nالزكاة المحسوبة: "+money(z));});box.addView(calc,new LinearLayout.LayoutParams(-1,dp(56)));Button close=btn("إغلاق");close.setOnClickListener(v->d.dismiss());box.addView(close,new LinearLayout.LayoutParams(-1,dp(52)));d.setContentView(box);d.show();Window w=d.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.92f),-2);}}
 EditText num(String h){EditText e=new EditText(this);e.setHint(h);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);e.setGravity(Gravity.CENTER);e.setBackground(bg(Color.WHITE));e.setPadding(dp(10),0,dp(10),0);if(c!=null)e.setTypeface(c);return e;}double val(EditText e){try{return Double.parseDouble(e.getText().toString().trim());}catch(Exception x){return 0;}}String money(double n){return String.format(Locale.US,"%.2f",n);}void card(View v){LinearLayout b=new LinearLayout(this);b.setPadding(dp(12),dp(12),dp(12),dp(12));b.setGravity(Gravity.CENTER);b.setBackground(bg(Color.WHITE));b.setElevation(dp(2));b.addView(v);LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,-2);q.setMargins(0,dp(7),0,0);root.addView(b,q);}void add(View v){LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,dp(56));q.setMargins(0,dp(7),0,0);root.addView(v,q);}Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setGravity(Gravity.CENTER);b.setTextSize(14);b.setBackground(bg(Color.WHITE));b.setElevation(dp(2));b.setMinHeight(0);b.setMinimumHeight(0);if(c!=null)b.setTypeface(c,1);return b;}TextView tx(String s,int z,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(color);t.setGravity(Gravity.CENTER);t.setPadding(dp(7),dp(7),dp(7),dp(7));if(c!=null)t.setTypeface(c,bold?1:0);return t;}GradientDrawable bg(int color){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(18));g.setStroke(dp(1),Color.rgb(231,218,188));return g;}int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
}
